numbercontrol.script:
function onDragStart(button, x, y, draginfo)
	draginfo.setType("ccwiz_swap");
	draginfo.setStringData(getName():gsub("^score_", ""));
	draginfo.setDescription(tostring(getValue()));
	return true;
end
function onDrop(x, y, draginfo)
	if draginfo.isType("ccwiz_swap") then
		CCWizard.swapScores(draginfo.getStringData(), getName():gsub("^score_", ""));
		return true;
	end
end

windowclass.script:
function onInit()
	update();
end
function setText(s)
	text.setValue(s);
end
function update()
	local bShow = CCWizard.getInstructionsShown();
	text.setVisible(bShow);
	button_toggle.setValue(bShow and 0 or 1);
end
function toggleInstructions()
	CCWizard.setInstructionsShown(not CCWizard.getInstructionsShown());
end

local _sKind = "race";
function setKind(sKind, sType)
	_sKind = sKind;
	local tFilter = CCWizard.getFilter(sKind);
	source.clear();
	source.add("", Interface.getString("ccwiz_label_allsources"));
	for _, s in ipairs(CCWizard.getSources(sType)) do
		source.add(s, s);
	end
	source.setValue(tFilter.source or "");
	if name.getValue() ~= (tFilter.name or "") then
		name.setValue(tFilter.name or "");
	end
end
function onSourceChanged(s)
	CCWizard.setFilter(_sKind, "source", s);
end
function onNameChanged(s)
	CCWizard.setFilter(_sKind, "name", s);
end

local _sPath = "";
local _sKind = "";
local _bSetting = false;
function setData(node, sKind)
	_sPath = DB.getPath(node);
	_sKind = sKind;
	local sName = DB.getValue(node, "name", "");
	local bBlocked = CCWizard.isBlocked(sName);
	local sReason = (sKind == "class") and CCWizard.getClassBlockReason(node) or nil;
	name.setValue(sName .. (bBlocked and "  (DM only)" or "") .. (sReason and ("  -  " .. sReason) or ""));
	add.setVisible(sReason == nil);
	if sReason then name.setColor("7F7F7F"); end
	source.setValue(CCWizard.getSourceName(node));
	allow.setVisible(Session.IsHost);
	_bSetting = true;
	allow.setValue(bBlocked and 0 or 1);
	_bSetting = false;
end
function onAdd()
	local node = DB.findNode(_sPath);
	if _sKind == "race" then
		CCWizard.selectRace(node);
	else
		CCWizard.selectClass(node);
	end
end
function onOpen()
	CCWizard.openRecord(_sPath);
end
function onAllow(bAllow)
	if _bSetting then return; end
	CCWizard.setBlocked(DB.getValue(DB.findNode(_sPath), "name", ""), not bAllow);
end

function setData(sTitle, sText, bOpen)
	title.setValue(sTitle);
	text.setValue(sText or "");
	setOpen(bOpen and (sText or "") ~= "");
end
function setOpen(bOpen)
	text.setVisible(bOpen);
	button_toggle.setValue(bOpen and 0 or 1);
end
function toggleCard()
	setOpen(not text.isVisible());
end

buttoncontrol.script:
function onInit()
	setColor(UtilityManager.getControlFontColor(window, "title"));
end
function onClickDown() return true; end
function onClickRelease() window.toggleCard(); return true; end

stringcontrol.script:
function onValueChanged()
	CCWizard.getState()[getName():gsub("^entry_", "")] = getValue();
	CCWizard.updateTabs();
	if window.updateSummary then
		window.updateSummary();
	end
end
